struct SDGlyph {
  uint32_t data_offset;
  uint16_t data_length;
  uint16_t width;
  uint16_t height;
  int16_t advance;
  int16_t x_offset;
  int16_t y_offset;
  uint8_t code;
};

struct SDFont {
  const uint8_t *data;
  const SDGlyph *glyphs;
  uint16_t glyph_count;
  int16_t ascent;
  int16_t descent;
};

// Keeps Arduino's generated prototype for get_page_text(PageText &) valid.
struct PageText;

